#include "../seam-carving-cuda/kernels_wrapper.h"
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
template<class T>T*alloc(int n){T*p;CK(cudaMalloc(&p,n*sizeof(T)));return p;}
template<class T>std::vector<T>read(const char*f){std::ifstream s(f,std::ios::binary|std::ios::ate);if(!s)exit(3);auto z=s.tellg();std::vector<T>a((size_t)z/sizeof(T));s.seekg(0);s.read((char*)a.data(),z);return a;}
int main(int argc,char**argv){const int w=128,h=128,S=100,N=w*h;int mode=atoi(argv[1]);bool diagnostic=argc>2&&std::string(argv[2])=="trace";auto input=read<uint32_t>("study_pixels_u32.bin");char name[100];sprintf(name,"study_expected_mode%d_u32.bin",mode);auto expected=read<uint32_t>(name);sprintf(name,"study_trace_mode%d_i32.bin",mode);auto expected_trace=read<int>(name);uchar4*p=alloc<uchar4>(N),*swap=alloc<uchar4>(N);short*l=alloc<short>(N),*u=alloc<short>(N),*r=alloc<short>(N),*ls=alloc<short>(N),*us=alloc<short>(N),*rs=alloc<short>(N);int*M=alloc<int>(N),*indices=alloc<int>(w),*ref=alloc<int>(w),*seam=alloc<int>(h),*index=alloc<int>(N),*offset=alloc<int>(N);std::vector<int>href(w);for(int i=0;i<w;i++)href[i]=i;CK(cudaMemcpy(ref,href.data(),w*4,cudaMemcpyHostToDevice));std::vector<int>trace;std::vector<uint32_t>before_pixels;
auto reset=[&](){CK(cudaMemcpy(p,input.data(),N*4,cudaMemcpyHostToDevice));if(mode==1)compute_costs(w,w,h,p,l,u,r);CK(cudaDeviceSynchronize());};
auto run=[&](bool capture){for(int step=0,cw=w;step<S;step++,cw--){if(mode==0)compute_costs(cw,w,h,p,l,u,r);if(mode<2){compute_M(cw,w,h,M,l,u,r);find_min_index(cw,ref,indices,M+w*(h-1));find_seam(cw,w,h,M,indices,seam);}else{approx_setup(cw,w,h,p,index,offset,M);approx_M(cw,w,h,offset,M);find_min_index(cw,ref,indices,M);approx_seam(w,h,index,indices,seam);}if(capture){std::vector<int>z(h);CK(cudaMemcpy(z.data(),seam,h*4,cudaMemcpyDeviceToHost));trace.insert(trace.end(),z.begin(),z.end());std::vector<uint32_t>hp(N);CK(cudaMemcpy(hp.data(),p,N*4,cudaMemcpyDeviceToHost));for(int row=0;row<h;row++)for(int col=0;col<cw;col++)before_pixels.push_back(hp[row*w+col]&0xffffff);}remove_seam(cw,w,h,M,p,swap,seam);std::swap(p,swap);if(mode==1){update_costs(cw,w,h,M,p,l,u,r,ls,us,rs,seam);std::swap(l,ls);std::swap(u,us);std::swap(r,rs);}}};
auto collect=[&](){std::vector<uint32_t>out=input;for(int a:{w,h,S,mode,1,w-S+1,w-S})out.push_back(a);std::vector<uint32_t>hp(N);CK(cudaMemcpy(hp.data(),p,N*4,cudaMemcpyDeviceToHost));for(int row=0;row<h;row++)for(int col=0;col<w-S;col++)out.push_back(hp[row*w+col]&0xffffff);std::vector<int>hs(h);CK(cudaMemcpy(hs.data(),seam,h*4,cudaMemcpyDeviceToHost));out.insert(out.end(),hs.begin(),hs.end());auto addints=[&](int*a,int rows,int cols){std::vector<int>z(N);CK(cudaMemcpy(z.data(),a,N*4,cudaMemcpyDeviceToHost));for(int row=0;row<rows;row++)for(int col=0;col<cols;col++)out.push_back(z[row*w+col]);};if(mode<2){addints(M,h,w-S+1);int cols=mode==1?w-S:w-S+1;for(short*a:{l,u,r}){std::vector<short>z(N);CK(cudaMemcpy(z.data(),a,N*2,cudaMemcpyDeviceToHost));for(int row=0;row<h;row++)for(int col=0;col<cols;col++)out.push_back(z[row*w+col]);}}else{addints(M,h-1,w-S+1);addints(index,h-1,w-S+1);addints(offset,h-1,w-S+1);}return out;};
std::string dir=getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".";
if(diagnostic){reset();run(true);CK(cudaDeviceSynchronize());auto out=collect();bool ok=out==expected&&trace==expected_trace;std::ofstream t(dir+"/native_trace_i32.bin",std::ios::binary);t.write((char*)trace.data(),trace.size()*4);std::ofstream a(dir+"/native_preseam_pixels_u32.bin",std::ios::binary);a.write((char*)before_pixels.data(),before_pixels.size()*4);printf("{\"diagnostic_only\":true,\"timing_series\":false,\"mode\":%d,\"all100_GPU_seams_equal_source_CPU_emulator\":%s,\"final_full_output_equals_CPU\":%s,\"trace_values\":%zu,\"preseam_RGB_pixel_values\":%zu}\n",mode,trace==expected_trace?"true":"false",out==expected?"true":"false",trace.size(),before_pixels.size());return ok?0:1;}
reset();run(false);CK(cudaDeviceSynchronize());bool all=true;for(int trial=1;trial<=5;trial++){reset();auto start=std::chrono::steady_clock::now();run(false);CK(cudaDeviceSynchronize());double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();auto out=collect();bool ok=out==expected;all&=ok;long long ma=0;double mr=0;for(size_t i=0;i<out.size();i++){long long e=llabs((long long)out[i]-expected[i]);ma=std::max(ma,e);mr=std::max(mr,e/std::max(1e-300,(double)expected[i]));}std::string fn=dir+"/output_trial"+std::to_string(trial)+".bin";std::ofstream f(fn,std::ios::binary);f.write((char*)out.data(),out.size()*4);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%lld,\"max_rel_error\":%.12g,\"error_metric_domain\":\"exact_RGB_lastseam_defined_DP_cost_or_greedy_maps_source_behavior_not_minimum_energy_guarantee\",\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":1,\"seams_removed\":100,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,sec,ok?"true":"false",out.size()-input.size()-7,ma,mr,fn.c_str(),out.size());fflush(stdout);}return all?0:1;}
